CREATE TABLE products (
    id INT PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    price NUMERIC(10,2) NOT NULL,
    stock INT DEFAULT 0
);

-- Batch insert 3 records in a single DML statement
INSERT INTO products (id, name, price, stock) VALUES
(1, 'Laptop', 1200.00, 10),
(2, 'Mouse', 25.00, 50),
(3, 'Keyboard', 75.00, 30);

SELECT COUNT(*) FROM products;

-- Increase prices by 10% strictly for low stock items
UPDATE products
SET price = price * 1.10
WHERE stock < 20;

SELECT name, price FROM products WHERE id = 1;

-- Delete product with id = 2
DELETE FROM products
WHERE id = 2;

SELECT id, name FROM products ORDER BY id;

CREATE TABLE audit_logs (
    log_id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    action VARCHAR(50) NOT NULL,
    recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Insert and immediately return generated identity and timestamp
INSERT INTO audit_logs (action)
VALUES ('USER_LOGIN')
RETURNING log_id, action, recorded_at;
